always-actions.script:
if (System.getProperty('sales.qa.disposable') != 'true' || !(ec.user.isInGroup('ADMIN') || ec.user.userId?.startsWith('AUDIT_QA_'))) {
    throw new org.moqui.context.ArtifactAuthorizationException('Disposable audit helper only.')
}

actions.script:
if (!ec.user.isInGroup('ADMIN') || !ec.entity.find('mantle.party.Party').condition('partyId','AUDIT_QA_A').disableAuthz().count() ||
        ec.entity.find('mantle.product.Product').condition('productId','AUDIT_VOL_P0').disableAuthz().count()) {
    ec.web.response.setStatus(409);ec.web.sendJsonResponse([loaded:false]);return
}
def xml = new StringBuilder('<entity-facade-xml>')
(0..<1500).each { i ->
    def org = i % 5 == 0 ? 'AUDIT_QA_B' : 'AUDIT_QA_A'
    xml.append("<mantle.product.Product productId=\"AUDIT_VOL_P${i}\" pseudoId=\"AUDIT_VOL_P${i}\" ownerPartyId=\"${org}\" productName=\"Disposable volume product ${i}\" productTypeEnumId=\"PtAsset\" amountUomId=\"OTH_ea\" inventoryTracked=\"Y\" mrpAmount=\"${1+i%100}\"/>")
}
(0..<200).each { i ->
    def org = i % 5 == 0 ? 'AUDIT_QA_B' : 'AUDIT_QA_A'
    xml.append("<mantle.party.Party partyId=\"AUDIT_VOL_C${i}\" ownerPartyId=\"${org}\" partyTypeEnumId=\"PtyPerson\"/><mantle.party.Person partyId=\"AUDIT_VOL_C${i}\" firstName=\"Disposable volume customer ${i}\"/><mantle.party.PartyRole partyId=\"AUDIT_VOL_C${i}\" roleTypeId=\"Customer\"/>")
}
(0..<300).each { i ->
    def org = i % 5 == 0 ? 'AUDIT_QA_B' : 'AUDIT_QA_A'
    xml.append("<zenith.erp.crm.Lead leadId=\"AUDIT_VOL_L${i}\" organizationPartyId=\"${org}\" firstName=\"Disposable volume lead ${i}\" statusId=\"LeadNew\" rating=\"Warm\" score=\"0\"/>")
}
xml.append('</entity-facade-xml>')
ec.entity.makeDataLoader().xmlText(xml.toString()).transactionTimeout(180).disableDataFeed(true).load()
ec.web.sendJsonResponse([loaded:!ec.message.hasError(),businessRecords:2000,errors:ec.message.errors])
